/// <summary>
/// Rebate deal contract class
/// </summary>
[DataContractAttribute]
public class METVendorRebateDealContract
{
    TAMRebateCurrencyCode tamRebateCurrencyCode;
    Description description;
    ModuleInventCustVend moduleInventCustVend;
    VendAccount vendAccount;
    TAMRebateDealId tamRebateDealId;
    TAMRebateOutputType tamRebateOutputType;
    TAMRebateReconciliation tamRebateReconciliation;
    TAMRebateType tamRebateType;
    METExternalRebateDealReference metExternalRebateDealReference;
    NoYes metUseExternalSellData;
    TAMRebatePostingId tamRebatePostingId;
    TAMRebateFromDate tamRebateFromDate;
    TAMRebateToDate tamRebateToDate;
    METRebateDealType metRebateDealType;

}

