/// <summary>
/// Curreny code
/// </summary>
/// <param name = "_tamRebateCurrencyCode">TAMRebateCurrencyCode</param>
/// <returns>TAMRebateCurrencyCode</returns>
[DataMemberAttribute(extendedTypeStr(TAMRebateCurrencyCode))]
public TAMRebateCurrencyCode parmTAMRebateCurrencyCode(TAMRebateCurrencyCode _tamRebateCurrencyCode = tamRebateCurrencyCode)
{
    tamRebateCurrencyCode = _tamRebateCurrencyCode;
    return tamRebateCurrencyCode;
}

